//! 深度卸载只批准准确 Bundle ID 的普通用户残留文件；不递归移动目录。
use crate::model::Entry;
use serde_json::{json,Value};
use std::os::macos::fs::MetadataExt as MacMetadataExt;
use std::{collections::{HashMap,HashSet},fs,os::unix::fs::MetadataExt,path::{Path,PathBuf},sync::{Mutex,OnceLock}};
#[derive(Clone)] struct Plan{app:Entry,entries:Vec<Entry>,reviewed:bool}
fn plans()-> &'static Mutex<HashMap<String,Plan>>{static P:OnceLock<Mutex<HashMap<String,Plan>>>=OnceLock::new();P.get_or_init(Default::default)}
fn bundle(app:&Entry)->Result<String,String>{
 if app.kind!="application"||!app.is_dir{return Err("仅接受后台应用扫描结果".into())}
 let p=Path::new(&app.path);let m=fs::symlink_metadata(p).map_err(|e|e.to_string())?;
 if !m.is_dir()||m.ino()!=app.inode||m.dev()!=app.device||fs::canonicalize(p).ok().as_deref()!=Some(p){return Err("应用身份或路径变化".into())}
 let v=plist::Value::from_file(p.join("Contents/Info.plist")).map_err(|_|"无法读取应用标识")?;
 let id=v.as_dictionary().and_then(|x|x.get("CFBundleIdentifier")).and_then(|x|x.as_string()).ok_or("缺少Bundle ID")?;
 if !id.contains('.')||id.starts_with("com.apple.")||!id.bytes().all(|b|b.is_ascii_alphanumeric()||b".-_".contains(&b)){return Err("应用标识不安全或受保护".into())}Ok(id.into())
}
fn candidate_paths(home:&Path,id:&str)->Vec<PathBuf>{vec![home.join("Library/Caches").join(id),home.join("Library/Logs").join(id),home.join("Library/Preferences").join(format!("{id}.plist")),home.join("Library/Saved Application State").join(format!("{id}.savedState"))]}
pub fn build_plan(app:&Entry)->Result<Value,String>{
 let id=bundle(app)?;crate::actions::ensure_uninstall_app_closed(Path::new(&app.path))?;let home=PathBuf::from(std::env::var_os("HOME").ok_or("缺少用户主目录")?);let ignored=crate::safety::load_ignored_paths()?;let mut entries=vec![app.clone()];
 for root in candidate_paths(&home,&id){if !root.exists(){continue}for e in walkdir::WalkDir::new(&root).follow_links(false).same_file_system(true){let Ok(e)=e else{continue};let p=e.path();let Ok(m)=fs::symlink_metadata(p)else{continue};if sensitive(p)||m.st_flags()!=0||!m.is_file()||m.nlink()!=1||m.uid()!=unsafe{libc::getuid()}||fs::canonicalize(p).ok().as_deref()!=Some(p)||crate::safety::matches_ignored(p,&ignored){continue}entries.push(Entry{id:format!("residue:{}:{}",m.dev(),m.ino()),name:e.file_name().to_string_lossy().into(),path:p.to_string_lossy().into(),size:m.len(),modified:Some(m.mtime().max(0)as u64),kind:"app_residue".into(),detail:"准确Bundle ID关联；仅普通文件；AI审核后仍需操作前复核".into(),is_dir:false,scope_root:home.join("Library").to_string_lossy().into(),inode:m.ino(),device:m.dev(),mtime_nsec:m.mtime_nsec()});}}
 let plan_id=uuid_token()?;plans().lock().map_err(|_|"计划锁失败")?.insert(plan_id.clone(),Plan{app:app.clone(),entries:entries.clone(),reviewed:false});Ok(json!({"event":"uninstall_plan","plan_id":plan_id,"items":entries.iter().map(|e|{let mut v=serde_json::to_value(e).unwrap();v["selected"]=json!(e.kind=="application"||e.path.contains("/Library/Caches/")||e.path.contains("/Library/Logs/"));v}).collect::<Vec<_>>(),"entries":entries,"application_names":[app.name],"errors":[],"reviewed":false,"notes":["Application Support、Containers、Group Containers、共享厂商目录、文档和凭证保留","仅列普通文件，空目录保留；读取失败项不授权","必须AI分析成功后再确认移入废纸篓"]}))
}
fn uuid_token()->Result<String,String>{use std::io::Read;let mut b=[0u8;24];fs::File::open("/dev/urandom").and_then(|mut f|f.read_exact(&mut b)).map_err(|_|"无法生成计划标识")?;Ok(b.iter().map(|x|format!("{x:02x}")).collect())}
pub fn analyze_plan(id:&str)->Result<Value,String>{let p=plans().lock().map_err(|_|"计划锁失败")?.get(id).cloned().ok_or("计划不存在")?;let mut v=crate::analysis::analyze(&p.entries,"uninstall");let reviewed=v["source"]=="ai";if reviewed{if let Some(p)=plans().lock().map_err(|_|"计划锁失败")?.get_mut(id){p.reviewed=true}}v["plan_id"]=json!(id);v["reviewed"]=json!(reviewed);Ok(v)}
pub fn approved_entries(id:&str,ids:&[String])->Result<Vec<Entry>,String>{let p=plans().lock().map_err(|_|"计划锁失败")?.get(id).cloned().ok_or("计划不存在")?;if !p.reviewed{return Err("必须先完成AI分析".into())}bundle(&p.app)?;crate::actions::ensure_uninstall_app_closed(Path::new(&p.app.path))?;let wanted:HashSet<_>=ids.iter().collect();if wanted.iter().any(|id|!p.entries.iter().any(|e|&e.id==*id)){return Err("选择包含计划外项目".into())}Ok(p.entries.into_iter().filter(|e|wanted.contains(&e.id)).collect())}
fn sensitive(p:&Path)->bool{p.components().any(|c|{let n=c.as_os_str().to_string_lossy().to_lowercase();n.contains("credential")||n.contains("keychain")||n.contains("token")||n.contains("password")||n==".ssh"||["pem","p12","pfx","key","sqlite","db"].iter().any(|ext|n.ends_with(&format!(".{ext}")))})}
pub fn validate_residue(e:&Entry)->Result<(),String>{let ps=plans().lock().map_err(|_|"计划锁失败")?;let p=ps.values().find(|p|p.reviewed&&p.entries.iter().any(|x|x.kind=="app_residue"&&x.id==e.id&&x.path==e.path&&x.inode==e.inode&&x.device==e.device&&x.size==e.size&&x.modified==e.modified&&x.mtime_nsec==e.mtime_nsec)).ok_or("残留未获精确计划批准")?;crate::actions::ensure_uninstall_app_closed(Path::new(&p.app.path))?;let m=fs::symlink_metadata(&e.path).map_err(|e|e.to_string())?;if sensitive(Path::new(&e.path))||m.st_flags()!=0||!m.is_file()||m.nlink()!=1||m.uid()!=unsafe{libc::getuid()}{return Err("残留类型、所有权或链接状态变化".into())}Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn candidates_exclude_shared_and_application_data(){let ps=candidate_paths(Path::new("/fixture"),"com.example.app");assert_eq!(ps.len(),4);assert!(ps.iter().all(|p|!p.to_string_lossy().contains("Application Support")&&!p.to_string_lossy().contains("Containers")));assert!(ps[2].ends_with("com.example.app.plist"));}#[test]fn nonexistent_plan_cannot_authorize(){assert!(approved_entries("untrusted",&[]).is_err());}}
